const images=new Map();let manifest=null,pending=null;
export async function loadCharacterArt(){if(pending)return pending;pending=(async()=>{const response=await fetch(new URL('./art/characters/manifest.json',import.meta.url));if(!response.ok)throw new Error('Character artwork is unavailable');manifest=await response.json();await Promise.all(Object.entries(manifest.assets).map(async([key,entry])=>{const image=new Image();image.src=new URL('./art/characters/'+entry.file,import.meta.url);await image.decode();images.set(key,image);}));return manifest;})();return pending;}
export function characterImage(id,view='south',gear='blindfold',combat=false){const direction=view==='west'?'side':view;if(combat&&images.has(`${id}-combat`))return images.get(`${id}-combat`);if(id==='gojo'&&direction!=='north'){const special=images.get(`gojo-${direction}-${gear}`);if(special)return special;}return images.get(`${id}-${combat?'combat':direction}`)||images.get(`${id}-${direction}`)||images.get(`${id}-south`);}
export function characterManifest(){return manifest;}
